async function* conDelay(items, ms) {
  for (const item of items) {
    await new Promise(r => setTimeout(r, ms));
    yield item;
  }
}

const resultados = [];

for await (const valor of conDelay([10, 20, 30], 10)) {
  resultados.push(valor);
}

const esArray = Array.isArray(resultados);
const total = resultados.length;

console.log('Resultados:', resultados);
console.log('Es array:', esArray, '| Total:', total);

const DB = [
  { id: 1, nombre: 'Ana' },
  { id: 2, nombre: 'Bob' },
  { id: 3, nombre: 'Carl' },
  { id: 4, nombre: 'Diana' },
  { id: 5, nombre: 'Eve' },
];

async function* paginar(datos, tamano) {
  for (let i = 0; i < datos.length; i += tamano) {
    await new Promise(r => setTimeout(r, 10)); // Simula query
    yield datos.slice(i, i + tamano);
  }
}

const paginas = [];
const todos = [];

for await (const pagina of paginar(DB, 2)) {
  paginas.push(pagina);
  todos.push(...pagina);
}

console.log('Páginas:', paginas.length);
console.log('Total elementos:', todos.length);
console.log('Primera página:', paginas[0]);

async function* fuente(items, ms) {
  for (const item of items) {
    await new Promise(r => setTimeout(r, ms));
    yield item;
  }
}

async function* transformar(stream, fn) {
  for await (const valor of stream) {
    yield fn(valor);
  }
}

async function* filtrarAsync(stream, pred) {
  for await (const valor of stream) {
    if (pred(valor)) yield valor;
  }
}

// Pipeline
const stream = fuente([1, 2, 3, 4, 5, 6], 5);
const multiplicado = transformar(stream, x => x * 3);
const filtrado = filtrarAsync(multiplicado, x => x % 6 === 0);

const resultado = [];
for await (const val of filtrado) {
  resultado.push(val);
}

console.log('Resultado:', resultado);
